function pyRepr(x) {
  if (Object.is(x, -0)) return '-0.0';
  const neg = x < 0; const a = Math.abs(x);
  if (a === 0) return neg ? '-0.0' : '0.0';
  const m = /^(\d)(?:\.(\d+))?e([+-]\d+)$/.exec(a.toExponential());
  const digits = m[1] + (m[2] || '');
  const exp = parseInt(m[3], 10);
  let s;
  if (exp < -4 || exp >= 16) {
    const mant = digits[0] + (digits.length > 1 ? '.' + digits.slice(1) : '');
    const ea = String(Math.abs(exp)).padStart(2, '0');
    s = mant + 'e' + (exp < 0 ? '-' : '+') + ea;
  } else if (exp >= 0) {
    s = digits.length <= exp + 1
      ? digits + '0'.repeat(exp + 1 - digits.length) + '.0'
      : digits.slice(0, exp + 1) + '.' + digits.slice(exp + 1);
  } else {
    s = '0.' + '0'.repeat(-exp - 1) + digits;
  }
  return neg ? '-' + s : s;
}
module.exports = { pyRepr };
